export const meta = {
  name: 'review-bot13-error-text',
  description: 'Read-only independent review of bot 1/3 error-text helper, check scripts, compare tool and analysis evidence',
  phases: [
    { title: 'Review', detail: 'three independent reviewers with different lenses' },
    { title: 'Verify', detail: 'adversarial verifier per reviewer batch' },
    { title: 'Critic', detail: 'completeness critic over verified results' },
  ],
}

const B = 'C:\\Users\\NTD\\Desktop\\Bot Market Demo\\'
const FILES = [
  'AGENTS.md',
  'dich-nguoc\\khoi-phuc\\PHAN-TICH-CHUOI-LOI-BOT-1-3.md',
  'dich-nguoc\\khoi-phuc\\bot-cua-toi-1\\source\\MQL5\\Include\\bot-cua-toi-1\\Bot1TradeErrors.mqh',
  'dich-nguoc\\khoi-phuc\\bot-cua-toi-3\\source\\MQL5\\Include\\bot-cua-toi-3\\Bot3TradeErrors.mqh',
  'dich-nguoc\\khoi-phuc\\bot-cua-toi-1\\source\\MQL5\\Scripts\\bot-cua-toi-1\\Bot1TradeErrorsCheck.mq5',
  'dich-nguoc\\khoi-phuc\\bot-cua-toi-3\\source\\MQL5\\Scripts\\bot-cua-toi-3\\Bot3TradeErrorsCheck.mq5',
  'dich-nguoc\\khoi-phuc\\cong-cu\\kiem-chuoi-loi-bot-1-3.py',
  'dich-nguoc\\khoi-phuc\\bot-cua-toi-1\\bang-chung\\kiem-chuoi-loi\\errors-20261024-r2\\analysis.json',
  'dich-nguoc\\khoi-phuc\\bot-cua-toi-3\\bang-chung\\kiem-chuoi-loi\\errors-20261024-r2\\analysis.json',
].map(p => B + p)

const RULES = [
  'CONTEXT: Authorized source-recovery project. The owner lost the MQL5 source of their own MT5 bots (bot 1 and bot 3) and is reconstructing it. Original EX5 files stay unchanged, license locks are not touched, tests run only in a private MT5 with trading disabled. This task is ONLY a read-only, independent review of an already-written piece: an error-code-to-text helper, its MQL5 check scripts, the Python compare tool, and the analysis evidence. It does not involve bypassing any protection. The MQL5 helper is not yet integrated into the EA.',
  '',
  'HARD CONSTRAINTS:',
  '- Use ONLY the Read and Grep tools, and ONLY on these 9 files (absolute paths below). Do not open, list, glob or grep anything else (not kiem-gui-lenh-bot-1-3.py, not Ghidra C files, not comparison.json, not build receipts).',
  '- Do NOT run shell/PowerShell/Bash/Python/MT5, do NOT write or edit any file, do NOT contact network services.',
  '- A "proven_defect" must be demonstrable purely from exact text in these 9 files; quote it with file:line. No speculation.',
  '- If something depends on an artifact outside these 9 files, classify it as "limitation" and name the exact missing artifact that would settle it.',
  '- "evidence_gap" = the visible test/evidence does not prove a claim it is used for (the code may still be right). "robustness" = fragile but not shown wrong.',
  '- Be precise with line numbers (Read shows them). Keep text concise.',
  '',
  'FILES:',
  ...FILES.map((f, i) => `${i + 1}. ${f}`),
  '',
  'USER QUESTIONS (Vietnamese, verbatim):',
  'Kiểm: tăng bộ đếm uint32 trước mọi nhánh và quay về 0, int32 có dấu ở nhánh mặc định, toàn bộ 92 mã/chuỗi phải chính xác, phần so kết quả có độc lập với mã mới không, thay chuỗi cũ có thể bị bỏ sót chỗ nào, kiểm biên dịch/nguồn/kết quả có đủ chắc không. Nêu lỗi có bằng chứng file:dòng, mức ảnh hưởng và cách kiểm. Phân biệt lỗi đã chứng minh với giới hạn chưa kiểm; không gọi 1.725 ca thành toàn bộ bot đạt 100%.',
  '',
].join('\n')

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          kind: { type: 'string', enum: ['proven_defect', 'evidence_gap', 'limitation', 'robustness'] },
          file: { type: 'string' },
          lines: { type: 'string' },
          claim: { type: 'string' },
          evidence: { type: 'string' },
          impact: { type: 'string', enum: ['high', 'medium', 'low'] },
          how_to_check: { type: 'string' },
        },
        required: ['id', 'kind', 'file', 'lines', 'claim', 'evidence', 'impact', 'how_to_check'],
      },
    },
    confirmed_ok: {
      type: 'array',
      items: {
        type: 'object',
        properties: { item: { type: 'string' }, evidence: { type: 'string' } },
        required: ['item', 'evidence'],
      },
    },
    not_verifiable: { type: 'array', items: { type: 'string' } },
  },
  required: ['findings', 'confirmed_ok', 'not_verifiable'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          refuted: { type: 'boolean' },
          quote_accurate: { type: 'boolean' },
          corrected_kind: { type: 'string', enum: ['proven_defect', 'evidence_gap', 'limitation', 'robustness', 'not_an_issue'] },
          corrected_impact: { type: 'string', enum: ['high', 'medium', 'low', 'none'] },
          reason: { type: 'string' },
        },
        required: ['id', 'refuted', 'quote_accurate', 'corrected_kind', 'corrected_impact', 'reason'],
      },
    },
    wrong_confirmed_ok: { type: 'array', items: { type: 'string' } },
  },
  required: ['verdicts', 'wrong_confirmed_ok'],
}

const LENSES = [
  {
    key: 'exactness',
    prompt: `YOUR LENS: exactness of the reconstructed helper (files 2-4 and 8-9; also file 7 lines 19-50 for CFG and analysis fields).
(a) For bot 1 and bot 3 separately, compare every line of the form case N:return "S"; in the .mqh against analysis.json "map" AND against the "literals" array (codes -> text). Character level: leading/trailing/double spaces, punctuation, apostrophes, parentheses, letter case, spelling. Original typos must be preserved, so report any deviation in either direction. Report the exact count of unique codes in each .mqh and each map, missing/extra codes, duplicates, and whether map and literals agree inside each analysis.json. Compare bot 1 vs bot 3 (helpers and maps).
(b) MQL5 semantics of the helper: counter type and where it is incremented relative to the switch and to every return path; MQL5 wrap behavior at 0xFFFFFFFF; default-branch text; what (string)code produces for const int code (signed int32 decimal?) for values like -1 and -2147483648; any path that skips the increment, double-increments, falls through, or returns without a value; compile pitfalls.
(c) Does PHAN-TICH-CHUOI-LOI-BOT-1-3.md describe the source and evidence accurately (function/counter/slot RVAs vs analysis.json and the tool CFG; claims vs what analysis.json actually contains)?
Use Grep to make comparisons mechanical where useful (e.g. count "case " lines, search non-ASCII [^\\x00-\\x7F], double spaces), only on the 9 files.`,
  },
  {
    key: 'independence',
    prompt: `YOUR LENS: does the test prove what it claims, independently of the new code? Read file 7 fully (especially cases(), Original.call/run, and modes 'mql5', 'original', 'compare') and files 5-6 fully.
(a) Data flow: for each field compared in 'compare' mode (id, counter, text), trace where the ORIGINAL value comes from and where the MQL5 value comes from. Identify every part of the ORIGINAL (expected) results that is derived from data produced by the MQL5 script under test, and state exactly what is and is not independently verified as a result (e.g. default-branch number text, its sign and width).
(b) Counter: is the u32 increment verified for every tested branch? Is wrap 0xFFFFFFFF -> 0 tested? Is the ordering "increment before the switch" observable by this test at all?
(c) Old shared string (old_kind 0/1/2): what does it exercise on the native side and on the MQL5 side? Where could replacement of the old string be missed or untested, both in the test and later when the helper is wired into the EA (the native writes into a shared string slot; the MQL5 returns a string)?
(d) Coverage: compute exactly the set and count of codes and rows produced by cases() from the 92-code map; list code ranges never executed; say precisely what the 1,725 figure does and does not cover.
(e) Binary format consistency between the MQL5 writer (FileWriteInteger / FileWriteString with FILE_BIN|FILE_UNICODE) and the Python encoder/reader, as far as visible.`,
  },
  {
    key: 'integrity',
    prompt: `YOUR LENS: analysis-parser robustness and the evidence chain. Read file 7 fully, files 8-9 and file 2.
(a) analyze(): regex extraction from Ghidra C. Which plausible Ghidra output shapes would it mis-handle or silently drop (negative or uppercase-hex case labels, a variable other than pMVar3, goto-shared blocks, a literal in the default branch, nested breaks)? Which analysis.json fields are extracted from data vs hardcoded constants? What does the hardcoded 92 check protect against and what not? Text decoding (read_text without encoding) and hashing (body.encode()) details.
(b) Evidence chain: what each mode verifies (EX5 hash, analysis/cases vs baseline, build receipt fields, source hashes, binary hash) and what 'compare' (and 'original') do NOT verify, e.g. whether original-results.bin / mql5-results.bin / cast-values.bin are the ones recorded in original-run.json / mql5-run.json, whether sources or binary changed after the MQL5 run, whether comparison.json can be overwritten.
(c) MT5 run: what the terminal process exit code means vs the script's OnStart return codes 1..6; whether script failures are still detected (fresh folder, parsing); include-path resolution of #include <bot-cua-toi-N/BotNTradeErrors.mqh> at compile time vs the hashed copy under home/source/MQL5.
(d) Status claims: from these 9 files alone, can anyone conclude that the comparison has been run and passed? What does PHAN-TICH-CHUOI-LOI-BOT-1-3.md itself say about status? Which doc claims rest only on hardcoded strings rather than extracted or measured data?`,
  },
]

const verifyPrompt = (key, review) => `YOUR ROLE: adversarial verifier. Another reviewer (lens: ${key}) produced the JSON below. For EACH finding: (1) open the cited file(s) and check the quoted text is really at the cited lines; (2) try hard to REFUTE it: does other code in the 9 files handle it, does the claim overstate the evidence, is it really only a limitation, is the impact inflated or deflated? (3) Give refuted, quote_accurate, corrected_kind, corrected_impact and a short reason with file:line. Default to refuted=true if the claim cannot be established from the 9 files alone. Also list any "confirmed_ok" item that is wrong.

REVIEWER OUTPUT:
${JSON.stringify(review)}`

phase('Review')
const results = await pipeline(
  LENSES,
  lens => agent(RULES + lens.prompt, { label: `review:${lens.key}`, phase: 'Review', schema: FINDINGS_SCHEMA, effort: 'max' }),
  (review, lens) => {
    if (!review) return null
    return agent(RULES + verifyPrompt(lens.key, review), { label: `verify:${lens.key}`, phase: 'Verify', schema: VERDICT_SCHEMA, effort: 'max' })
      .then(verdict => ({ lens: lens.key, review, verdict }))
  },
)

const done = results.filter(Boolean)
log(`reviews with verdicts: ${done.length}/${LENSES.length}`)

phase('Critic')
const critic = await agent(RULES + `YOUR ROLE: completeness critic. Below are the reviews with adversarial verdicts. Using Read/Grep on the 9 files only, find what is still missing: user questions not fully answered, file regions not examined, wrong classifications, claims accepted without evidence, and any new issue. Return only NEW or CORRECTED findings (same schema), plus confirmed_ok and not_verifiable lists.

REVIEWS AND VERDICTS:
${JSON.stringify(done)}`, { label: 'critic', phase: 'Critic', schema: FINDINGS_SCHEMA, effort: 'max' })

return { results: done, critic }
